<?php

use App\Actions\ResetUserPassword;
use App\Models\User;
use App\Support\TemporaryPassword;
use Flux\Flux;
use Livewire\Attributes\Locked;
use Livewire\Attributes\Title;
use Livewire\Component;

new #[Title('Reset password')] class extends Component
{
    #[Locked]
    public User $user;

    /**
     * The password the administrator chooses.
     */
    public string $password = '';

    /**
     * Whether the temporary password is generated by the application.
     */
    public bool $generatePassword = true;

    /**
     * Whether the account holder has to choose their own password.
     */
    public bool $mustChangePassword = true;

    /**
     * The temporary password that was handed out, shown only once.
     */
    public ?string $issuedPassword = null;

    /**
     * Mount the component.
     */
    public function mount(User $user): void
    {
        $this->authorizeAccountManagement();

        $this->user = $user;
    }

    /**
     * Only an administrator may manage user accounts.
     */
    public function authorizeAccountManagement(): void
    {
        abort_unless(
            auth()->user()?->can(\App\Enums\Permission::ManageUserAccounts) ?? false,
            403,
        );
    }

    /**
     * Perform the reset.
     */
    public function resetPassword(): void
    {
        $this->authorizeAccountManagement();

        $this->validate([
            'password' => ['nullable', 'string', 'min:8', 'max:255'],
        ]);

        $password = $this->generatePassword || $this->password === ''
            ? TemporaryPassword::generate()
            : $this->password;

        app(ResetUserPassword::class)->handle($this->user, $password, $this->mustChangePassword);

        $this->issuedPassword = $password;
        $this->password = '';

        Flux::toast(variant: 'success', text: __('The password was reset.'));
    }
};
?>

<div class="flex h-full w-full flex-1 flex-col gap-6">
    <header>
        <flux:heading level="1" size="xl">{{ __('Reset the password') }}</flux:heading>
        <flux:text class="mt-1">
            {{ __(':name (:email)', ['name' => $user->name, 'email' => $user->email]) }}
        </flux:text>
    </header>

    @if ($issuedPassword)
        <flux:callout color="lime" icon="check-circle" class="max-w-2xl">
            <flux:heading size="sm">{{ __('The password was reset.') }}</flux:heading>
            <flux:text>
                {{ __('Hand this password over to the account holder directly. It is shown only once.') }}
            </flux:text>
            <flux:text class="font-mono text-lg font-semibold">{{ $issuedPassword }}</flux:text>
        </flux:callout>

        <div class="flex gap-3">
            <flux:button :href="route('admin.users.index')" variant="ghost">
                {{ __('Back to the accounts') }}
            </flux:button>

            <flux:button variant="primary" wire:click="$set('issuedPassword', null)">
                {{ __('Reset another password') }}
            </flux:button>
        </div>
    @else
        <div class="max-w-2xl space-y-6 rounded-xl border border-zinc-200 p-6 dark:border-zinc-700">
            <flux:callout color="amber" icon="exclamation-triangle">
                {{ __('The deployment cannot send mail. The password has to be handed over to the account holder directly.') }}
            </flux:callout>

            <flux:checkbox wire:model="generatePassword" :label="__('Generate a temporary password')" />

            @unless ($generatePassword)
                <flux:input
                    wire:model="password"
                    :label="__('New password')"
                    type="text"
                    autocomplete="new-password"
                    :error="$errors->first('password')"
                />
            @endunless

            <flux:checkbox
                wire:model="mustChangePassword"
                :label="__('Require a password change at the next sign in')"
            />

            <div class="flex justify-end gap-3">
                <flux:button :href="route('admin.users.index')" variant="ghost"> {{ __('Cancel') }} </flux:button>

                <flux:button variant="primary" wire:click="resetPassword"> {{ __('Reset password') }} </flux:button>
            </div>
        </div>
    @endif
</div>
